AI_NUMBERS={1,4,6,7,9,12,13,14,16,17,20,21,22,23,26,28,29,30}

def revise(styles):
 import json
 from pathlib import Path
 root=Path(__file__).resolve().parents[1]
 baseline=json.loads((root/'records/infopro-stable-ids.json').read_text())
 known={s['name']:s for s in styles}
 target=[s for s in styles if s['family']=='infoprodutores']
 assert len(target)==len(ROWS)==len(baseline)==30
 for n,(s,line,old) in enumerate(zip(target,ROWS,baseline),1):
  name,visual,topic,need,resources,motion,nearest,distinction,sound=line.split('|')
  s.update(name=name,signature=visual,exampleTopic=topic,uses=need,resources=resources.split('; '),motion=motion,revision='3.2',previousName=old['name'])
  assert s['id']==old['id']
  s['novelty']={'nearestId':known[nearest]['id'],'nearestName':nearest,'difference':distinction}
  s['proof']='Nos 10 segundos, executar esta sequência: '+motion+'. Avaliar utilidade da mensagem, legibilidade, voz e continuidade; a amostra estática não prova movimento.'
  s['preset']['quality']=s['proof'];s['audio']['sfx']=sound
  s['audio']['music']='Trilha licenciada adequada à direção; reduzir ou desligar onde disputar atenção com fala, instrução ou evidência.'
  s['audio']['voice']='Locução natural e específica ao roteiro. Fala original autorizada quando a presença do especialista/aluno for parte da evidência; não fabricar testemunhos.'
  s['visualLanguage']=visual.split(':')[0].split(',')[0].split(';')[0]
  s['segment']='Venda e aquisição' if n in {3,4,19,20,21,22,23,28} else 'Ensino e demonstração' if n in {1,2,5,6,9,10,11,12,13,16,25,26,29} else 'Experiência do aluno'
  s['kind']=s['segment']
  s['researchRefs']=['info-launch','info-marketing','info-formats'] if s['segment']=='Venda e aquisição' else ['info-membership','teachable','vanderbilt'] if s['segment']=='Experiência do aluno' else ['vanderbilt','info-lighting','info-formats']
  mode='ai' if n in AI_NUMBERS else 'code'
  s['image']={'atlas':f'assets/infopro-r2-{n:02d}.webp','column':0,'row':0,'columns':1,'rows':1,'sourceKind':mode,'source':'Estudo fotográfico IA fictício' if mode=='ai' else 'Estudo editorial/UI em código, demonstrativo'}
  s['note']='Amostra estática conceitual: '+('pessoas, ambientes e trabalhos fictícios gerados por IA; não são alunos, depoimentos ou resultados reais.' if mode=='ai' else 'layout vetorial ou interface demonstrativa criada em código; não é captura de uma plataforma real.')+' Na produção, usar fontes originais autorizadas e aplicar revisão de identidade, naturalidade e fidelidade. Não confundir estudo de aparência com vídeo executado.'
